# orbitmines/physics/theorems - what the rules come to, as something to look up: every theorem, keyed by
# theory and then by question. GENERATED by `npx ray gen` from implementation/physics.ray. Do not edit.
require "json"

module OrbitMines
  module Physics
    module Theorems
      PROVED = JSON.parse(File.read(File.join(__dir__, "theorems.json")))

      # one theorem, or nothing - and never a raise
      def self.proved(of, theory, theorem) = (of[theory] || {})[theorem]
      # which theories have an answer to a question
      def self.theories(of, theorem) = of.keys.select { |t| of[t].key?(theorem) }
      # every question a theory answers
      def self.asked(of, theory) = (of[theory] || {}).keys
    end
  end
end
